@extends('layouts.app') @section('title','Nueva compra') @section('content')<div><h1>Registrar compra</h1><p class="mt-2 text-sm text-slate-500">El inventario cambiará al confirmar la recepción.</p></div><form method="POST" action="{{ route('purchases.store') }}" class="card space-y-6 p-7" x-data="{items:{{ json_encode(old('items',[['product_id'=>'','quantity'=>1,'unit_price'=>'0.00','discount'=>'0.00']])) }}}">@csrf<input type="hidden" name="idempotency_key" value="{{ old('idempotency_key',(string)Str::uuid()) }}"><label>Proveedor<select name="supplier_id" required><option value="">Seleccionar proveedor</option>@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}" @selected(old('supplier_id')==$supplier->id)>{{ $supplier->name }}</option>@endforeach</select></label><template x-for="(item,index) in items" :key="index"><div class="grid items-end gap-4 rounded-xl border border-slate-200 p-4 md:grid-cols-5 dark:border-slate-700"><label>Producto<select :name="`items[${index}][product_id]`" x-model="item.product_id" required><option value="">Seleccionar</option>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->sku }} · {{ $product->name }}</option>@endforeach</select></label><label>Cantidad<input type="number" min="1" max="100000" step="1" :name="`items[${index}][quantity]`" x-model="item.quantity" required></label><label>Costo unitario USD<input type="number" min="0" step="0.01" :name="`items[${index}][unit_price]`" x-model="item.unit_price" required></label><label>Descuento de línea USD<input type="number" min="0" step="0.01" :name="`items[${index}][discount]`" x-model="item.discount"></label><button type="button" class="btn-secondary" @click="items.splice(index,1)" :disabled="items.length===1">Quitar</button></div></template><button type="button" class="btn-secondary" @click="items.push({product_id:'',quantity:1,unit_price:'0.00',discount:'0.00'})" :disabled="items.length>=100">Agregar producto</button><p class="text-sm text-slate-500">Los impuestos se toman de cada producto y se calculan en el servidor. No repitas un producto en distintas líneas.</p><div class="flex gap-3"><button class="btn">Guardar compra pendiente</button><a class="btn-secondary" href="{{ route('purchases.index') }}">Cancelar</a></div></form>@endsection
